-- Universal copy/paste
do
    local function clipboard_action(key)
        return function()
            local window = hl.get_active_window()
            local class = window and (window.class or ""):lower() or ""
            local mods = class:match("^foot") and "CTRL + SHIFT" or "CTRL"

            hl.dispatch(hl.dsp.send_key_state({
                mods = mods, key = key, state = "down"
            }))
            hl.timer(function()
                hl.dispatch(hl.dsp.send_key_state({
                    mods = mods, key = key, state = "up"
                }))
            end, { timeout = 50, type = "oneshot" })
        end
    end
    hl.bind("SUPER + X", clipboard_action("X"),
        { description = "Universal cut" })
    hl.bind("SUPER + C", clipboard_action("C"),
        { description = "Universal copy" })
    hl.bind("SUPER + V", clipboard_action("V"),
        { description = "Universal paste" })
end

-- Start the password-prompt agent and Caelestia with Hyprland
hl.on("hyprland.start", function()
    hl.exec_cmd("systemctl --user start hyprpolkitagent.service")
    hl.exec_cmd("caelestia shell -d")
end)

-- Blur translucent shell pixels; ignore_alpha = 0 excludes fully transparent pixels.
function applyCaelestiaDashboardBlur(refresh)
    hl.config({
        decoration = { blur = { enabled = true, size = 2, passes = 3, new_optimizations = false } },
        render = { use_shader_blur_blend = false },
    })
    caelestiaDashboardBlurRule = hl.layer_rule({
        name = "caelestia-dashboard-live-blur",
        match = { namespace = "^caelestia-drawers$" },
        blur = true,
        ignore_alpha = 0,
        xray = false,
    })
    if refresh then
        caelestiaDashboardBlurRule:set_enabled(true)
    end
end

applyCaelestiaDashboardBlur()

-- Per-machine settings are created once and never overwritten by the installer.
require("machine")
